'use strict';
let ornFeatures=[],ornLayer=null;
state.roadOverrides=state.roadOverrides||{};state.roadScenario=state.roadScenario||{enabled:false,paved:40,unpaved:25};
$('useorn').checked=state.roadScenario.enabled;$('pavedspeed').value=state.roadScenario.paved;$('unpavedspeed').value=state.roadScenario.unpaved;
const ornAttribution='Road data © King’s Printer for Ontario · <a href="https://data.ontario.ca/dataset/ontario-road-network-orn-composite">Open Government Licence – Ontario</a>';
function ornName(f){const p=f.properties;return p.FULL_STREET_NAME||p.ABBREVIATED_STREET_NAME||(p.ROUTE_NUMBER?'Highway '+p.ROUTE_NUMBER:'Unnamed road · '+p.OBJECTID)}
function ornParts(f){return f.geometry.type==='LineString'?[f.geometry.coordinates]:f.geometry.type==='MultiLineString'?f.geometry.coordinates:[]}
function scenarioRoads(force=false,settings=null){if(!force&&!$('useorn').checked)return[];let routes=[];for(const f of ornFeatures){const p=f.properties,o=state.roadOverrides[p.OBJECTID]||{},flow=p.DIRECTION_OF_TRAFFIC_FLOW;if(o.access==='closed'||p.ROAD_ELEMENT_TYPE!=='ROAD ELEMENT'||!['Both','Positive','Negative'].includes(flow))continue;let speed=o.speed||(p.PAVEMENT_STATUS==='Paved'?Number(settings?.paved??$('pavedspeed').value):p.PAVEMENT_STATUS==='Unpaved'?Number(settings?.unpaved??$('unpavedspeed').value):0);if(p.SPEED_LIMIT>0)speed=Math.min(speed,p.SPEED_LIMIT);if(!(speed>0))continue;for(const [i,path]of ornParts(f).entries())routes.push({id:'orn-'+p.OBJECTID+'-'+i,name:ornName(f),coords:path.map(c=>[c[1],c[0]]),speed,status:'Assumed passable',direction:flow==='Positive'?'forward':flow==='Negative'?'reverse':'both',source:'ORN'})}return routes}
function ornScenarioNote(){return $('useorn').checked?'ORN scenario included: unreviewed roads assumed passable; speeds are planning assumptions.':'ORN scenario off.'}
function ornStats(){const paved=ornFeatures.filter(f=>f.properties.PAVEMENT_STATUS==='Paved').length,unpaved=ornFeatures.filter(f=>f.properties.PAVEMENT_STATUS==='Unpaved').length;$('ornsummary').textContent=`${ornFeatures.length} source segments: ${paved} paved, ${unpaved} unpaved. Full segments intersecting a buffered rectangular window around your Response Area were retained. Attributes describe source records, not current tanker access.`;$('ornstatus').textContent=`${ornFeatures.length} ORN segments · imported snapshot`;$('ornscenarioinfo').textContent=$('useorn').checked?`${scenarioRoads().length} source paths included under assumptions. Mark individual roads closed / excluded in Roads when needed.`:'Source roads are displayed, but excluded from travel estimates until enabled.'}
function dateText(v){return v?new Date(v).toISOString().slice(0,10):'Unknown'}
function editOrn(f,zoom=false){const p=f.properties,o=state.roadOverrides[p.OBJECTID]||{};if(zoom)map.fitBounds(L.geoJSON(f).getBounds(),{padding:[60,60],maxZoom:15});$('ornid').value=p.OBJECTID;$('orntitle').textContent=ornName(f);$('ornfields').innerHTML=`<p class="hint">Source attributes · ORN Composite</p><dl class="roadfacts"><dt>Pavement</dt><dd>${esc(p.PAVEMENT_STATUS||'Unknown')}</dd><dt>Road class</dt><dd>${esc(p.ROAD_CLASS||'Unknown')}</dd><dt>Recorded speed limit</dt><dd>${p.SPEED_LIMIT>0?esc(p.SPEED_LIMIT)+' km/h':'Unknown'}</dd><dt>Traffic direction</dt><dd>${esc(p.DIRECTION_OF_TRAFFIC_FLOW||'Unknown')}</dd><dt>Jurisdiction</dt><dd>${esc(p.JURISDICTION||'Unknown')}</dd><dt>Route number</dt><dd>${esc(p.ROUTE_NUMBER||'Not recorded')}</dd><dt>Source geometry update</dt><dd>${dateText(p.GEOMETRY_UPDATE_DATETIME)}</dd><dt>Source effective date</dt><dd>${dateText(p.EFFECTIVE_DATETIME)}</dd><dt>Segment / road element ID</dt><dd>${esc(p.OBJECTID)} / ${esc(p.ROAD_NET_ELEMENT_ID)}</dd></dl>`;$('ornaccess').value=o.access||'unreviewed';$('ornoverridespeed').value=o.speed??'';$('ornnotes').value=o.notes||'';$('orneditor').showModal()}
function listOrn(){let q=$('ornsearch').value.trim().toLowerCase(),matches=ornFeatures.filter(f=>[ornName(f),f.properties.ROUTE_NUMBER,f.properties.ROAD_CLASS,f.properties.PAVEMENT_STATUS].join(' ').toLowerCase().includes(q)).sort((a,b)=>ornName(a).localeCompare(ornName(b)));$('ornlist').innerHTML='';for(const f of matches.slice(0,12)){let b=document.createElement('button');b.className='item';b.innerHTML=`<strong>${esc(ornName(f))}</strong><small>${esc(f.properties.PAVEMENT_STATUS)} · ${esc(f.properties.ROAD_CLASS)}<br>Recorded limit: ${f.properties.SPEED_LIMIT||'unknown'} km/h · ${state.roadOverrides[f.properties.OBJECTID]?.access==='closed'?'locally excluded':'access unverified'}</small>`;b.onclick=()=>editOrn(f,true);$('ornlist').appendChild(b)}$('ornmatches').textContent=`Showing ${Math.min(12,matches.length)} of ${matches.length} matches. Search or click road lines on the map to inspect others.`}
$('ornsearch').oninput=listOrn;$('orncancel').onclick=()=>$('orneditor').close();$('ornform').onsubmit=e=>{e.preventDefault();const id=$('ornid').value;state.roadOverrides[id]={access:$('ornaccess').value,speed:$('ornoverridespeed').value===''?null:Number($('ornoverridespeed').value),notes:$('ornnotes').value};save();$('orneditor').close();listOrn();ornStats();computeCoverage();if(ornLayer)ornLayer.setStyle(ornStyle);window.dispatchEvent(new Event('network-assumptions-changed'))};
function ornStyle(f){const excluded=state.roadOverrides[f.properties.OBJECTID]?.access==='closed';return{color:excluded?'#ad5146':f.properties.PAVEMENT_STATUS==='Paved'?'#586d77':'#a98958',weight:2.5,opacity:.85,dashArray:excluded?'4 5':null}}
for(const id of ['useorn','pavedspeed','unpavedspeed'])$(id).oninput=()=>{state.roadScenario={enabled:$('useorn').checked,paved:Number($('pavedspeed').value),unpaved:Number($('unpavedspeed').value)};save();ornStats();computeCoverage()};
$('ornvisible').onchange=()=>{if(!ornLayer)return;if($('ornvisible').checked){ornLayer.addTo(map);map.attributionControl.addAttribution(ornAttribution)}else{map.removeLayer(ornLayer);map.attributionControl.removeAttribution(ornAttribution)}};
fetch('roads.geojson').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(data=>{ornFeatures=data.features;ornLayer=L.geoJSON(data,{style:ornStyle,onEachFeature:(f,l)=>{l.bindTooltip(esc(ornName(f))+' · '+esc(f.properties.PAVEMENT_STATUS));l.on('click',()=>{if(!mode)editOrn(f)})}});if($('ornvisible').checked){ornLayer.addTo(map);map.attributionControl.addAttribution(ornAttribution)}ornStats();listOrn();computeCoverage();window.dispatchEvent(new Event('geodata-ready'))}).catch(e=>{$('ornsummary').textContent='Unable to load ORN road data. Reload to try again.';$('ornstatus').textContent='ORN layer unavailable';console.error('ORN roads:',e.message)});
function ornExportFeatures(){return ornFeatures.map(f=>({...f,properties:{...f.properties,record_type:'orn_road',source:'Ontario Road Network Composite',license:'Open Government Licence – Ontario',local_assumption:state.roadOverrides[f.properties.OBJECTID]||null}}))}
